/**
 * The router: provider registry + dispatch.
 *
 * Usage:
 *   import { completeForRole } from "@secscan/redteam-llm-router";
 *   const res = await completeForRole("exploiter", [
 *     { role: "system", content: EXPLOITER_PROMPT },
 *     { role: "user", content: "Begin phase 2." },
 *   ], { tools: harnessTools });
 *
 * completeForRole() applies ROLE_MODEL_POLICY automatically. complete() lets
 * callers pick provider+model explicitly. Unknown provider ids and
 * unconfigured providers (missing API key) throw with actionable messages.
 */
import type { AgentRole, ChatMessage, ChatResult, CompleteOptions, JsonSchemaTool, LlmProvider } from "./types.js";
export declare function registerProvider(provider: LlmProvider): void;
export declare function listProviders(): Array<{
    id: string;
    label: string;
    configured: boolean;
}>;
export declare function complete(providerId: string, options: CompleteOptions): Promise<ChatResult>;
export declare function completeForRole(role: AgentRole, messages: ChatMessage[], opts?: {
    tools?: JsonSchemaTool[];
    signal?: AbortSignal;
    maxTokens?: number;
    temperature?: number;
}): Promise<ChatResult>;
